-- name: entity-cluster-distribution
-- params: 
WITH em AS (SELECT e.id AS id, (SELECT count(DISTINCT fn.symbol) FROM "FUNCTION_MENTIONS" m JOIN Function fn ON fn.symbol = m.src WHERE m.dst = e.id AND NOT (instr(fn.file, 'tests/') > 0) AND NOT (instr(fn.symbol, 'tests/') > 0)) AS function_mentions, (SELECT count(DISTINCT t.symbol) FROM "TYPE_MENTIONS" m JOIN Type t ON t.symbol = m.src WHERE m.dst = e.id AND NOT (instr(t.file, 'tests/') > 0) AND NOT (instr(t.symbol, 'tests/') > 0)) AS type_mentions, (SELECT count(DISTINCT fn2.symbol) FROM "FUNCTION_BELONGS_TO" m JOIN Function fn2 ON fn2.symbol = m.src WHERE m.dst = e.id AND NOT (instr(fn2.file, 'tests/') > 0) AND NOT (instr(fn2.symbol, 'tests/') > 0)) AS belongs_count  FROM Entity e),
g AS (SELECT id, CASE WHEN type_mentions = 0 THEN 'function-heavy' WHEN 1.0 * function_mentions / type_mentions >= 2.0 THEN 'function-heavy' WHEN 1.0 * function_mentions / type_mentions <= 1.5 THEN 'type-heavy' ELSE 'balanced' END AS flavor_label, CASE WHEN belongs_count = 0 THEN 'pure-discussion' WHEN function_mentions = 0 THEN 'pure-structural' WHEN 1.0 * belongs_count / function_mentions >= 2.0 THEN 'implementation-heavy' WHEN 1.0 * belongs_count / function_mentions <= 0.7 THEN 'discussion-heavy' ELSE 'balanced' END AS lifecycle_label FROM em WHERE function_mentions >= 1 OR type_mentions >= 1 OR belongs_count >= 1)
SELECT cluster_label, count(*) AS entity_count FROM (SELECT CASE WHEN lifecycle_label = 'pure-discussion' THEN 'future-work' WHEN flavor_label = 'type-heavy' AND lifecycle_label = 'implementation-heavy' THEN 'implemented-infrastructure' WHEN flavor_label = 'function-heavy' AND lifecycle_label = 'discussion-heavy' THEN 'discussed-handlers' WHEN flavor_label = 'function-heavy' AND lifecycle_label = 'balanced' THEN 'architectural-center' WHEN flavor_label = 'balanced' AND lifecycle_label = 'implementation-heavy' THEN 'implementation-anomaly' ELSE 'unclassified' END AS cluster_label FROM g)
GROUP BY cluster_label ORDER BY entity_count DESC, cluster_label;
